package com.twilightecho.android.feature.player

import com.twilightecho.android.coreclient.DefaultCoreClient
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test

class AudioMonitorPresentationTest {
    @Test fun nativePeakBandsReachThePlayerWithoutASecondFrequencyConversion() {
        // Generated by the production FftSpectrumAnalyzer: 48 kHz stereo,
        // 8192 frames, bin 171 (1001.953125 Hz), amplitude 0.5.
        val text = javaClass.getResourceAsStream("/audio-monitor-native.json")!!.bufferedReader().use { it.readText() }
        val visualization = DefaultCoreClient.DefaultJson.parseToJsonElement(text).jsonObject
        val levels = audioMonitorLevels(visualization)
        assertEquals(48, levels.size)
        assertTrue(levels.max() > 0.83f)
        assertTrue(levels.max() < 0.85f)
        assertEquals(27, levels.indexOf(levels.max()))
        assertTrue(visualization["spectrum"]!!.jsonArray.isEmpty())
        assertEquals("peak", visualization["visualizerBarMode"]!!.jsonPrimitive.content)
        assertEquals(visualization["visualizerBars"]!!.jsonArray.map { it.jsonPrimitive.float }, levels)
    }

    @Test fun noNativeCaptureClearsTheBarsRatherThanKeepingThePreviousTone() {
        val zeros = buildJsonObject { put("visualizerBars", buildJsonArray { repeat(48) { add(0) } }) }
        assertEquals(List(48) { 0f }, audioMonitorLevels(zeros))
        assertEquals(emptyList<Float>(), audioMonitorLevels(JsonObject(emptyMap())))
    }

    @Test fun normalizedDisplayBoundsRemainTheExistingPlayerContract() {
        val raw = buildJsonObject { put("visualizerBars", buildJsonArray { add(-0.1); add(0.3); add(1.1) }) }
        assertEquals(listOf(0f, 0.3f, 1f), audioMonitorLevels(raw))
    }
}
